using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver (resolves any type)
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): safe probe without exception ---
// This will succeed because the default resolver can handle Person.
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
}

// Now use a *source-gen* context that only knows about Person.
// Asking for a type NOT in that context should return false.
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = SmallContext.Default
};

if (restrictedOptions.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
{
    Console.WriteLine($"TryGetTypeInfo<int[]> succeeded (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int[]> returned false — metadata not available (no exception thrown)");
}

// Confirm the restricted context DOES resolve Person:
if (restrictedOptions.TryGetTypeInfo<Person>(out var personInfo2))
{
    Console.WriteLine($"TryGetTypeInfo<Person> on restricted context succeeded: {personInfo2!.Type.Name}");
}

